sys_script_include.script:
var FileMakerAjaxUtils = Class.create();
FileMakerAjaxUtils.prototype = Object.extendsObject(AbstractAjaxProcessor, {

    getSingleGroup: function() {
        var appId = this.getParameter('sysparm_app_id');

        // Target your exact security groups table
        var grGroup = new GlideRecord('x_sogs_filemaker_a_filemaker_security_groups'); 

        // Ensure this matches the reference field column name on the security group table
        grGroup.addQuery('application_id', appId); 
        grGroup.query();

        // If exactly one group exists for this application, return its sys_id
        if (grGroup.getRowCount() == 1) {
            if (grGroup.next()) {
                return grGroup.getUniqueValue();
            }
        }

        // Return empty string if 0 or multiple groups exist
        return ''; 
    },

    type: 'FileMakerAjaxUtils'
});
